using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class InspectStreetRiders {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Idle required");EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");var d=Object.FindFirstObjectByType<Chapter45Director>();return new{riders=d.hazards.Where(h=>h.name.Contains("kickboard")||h.name.Contains("motorcycle")).Select(h=>new{name=h.name,position=new[]{h.body.localPosition.x,h.body.localPosition.y,h.body.localPosition.z},children=h.body.Cast<Transform>().Select(t=>t.name).ToArray(),animators=h.body.GetComponentsInChildren<Animator>(true).Select(a=>new{name=a.name,isHuman=a.isHuman,enabled=a.enabled}).ToArray(),bones=h.body.GetComponentsInChildren<SkinnedMeshRenderer>(true).SelectMany(s=>s.bones).Where(b=>b!=null).Select(b=>b.name).Distinct().ToArray()}).ToArray()};}}
